INSERT INTO "sources" VALUES('S18_linkedin','Career Finder Folder\Resume Optimization Tool\sources\linkedin_2026-09-25.md','b594acde2a787aae7c79a2f4a4b77ffa','LinkedIn public profile (captured 2026-09-25)','linkedin_md','Sales Professional | Marketing, Advertising, Product, Services, & Sales GTM Strategist Providing Advisory Services | Systems Thinker | Process Engineer | AI Adoption Enthusiast','2026-09-25 18:04:07');
INSERT INTO "summaries" VALUES(1,NULL,'["gtm-strategy", "new-business", "full-cycle-sales"]','Revenue and go-to-market operator with eight years of full-cycle B2B, media, and enterprise technology sales, currently advising the CEO and board of an AI start-up on go-to-market, pricing, and buy-vs-build strategy. Wins net-new business from cold — Fortune 500 accounts at TEKsystems, NFL and MLB team partnerships at Professional Sports Publications — by qualifying on the budget that can actually fund a buy and building the CPM, CPA, and unit-economics case a client''s finance team can defend. Has led a team of up to five, coaching performance against daily process and 1:1 metrics, and uses Claude and OpenAI models daily to compress research, account mapping, and proposal cycles.','baseline','accepted');
INSERT INTO "summaries" VALUES(2,'R3_fundraising','["moves-management", "institutional-partnerships", "funding-source-diagnostics"]','Eight years of relationship-driven revenue work built on the cycle advancement runs on: identify, qualify, cultivate, solicit, close, steward. Currently structures institutional partnerships for independent schools, chambers of commerce, and 501(c)(3) organizations — matching every ask to the funding source that can fund it. Writes the proposal, handles the objection, and builds the case a champion can carry to her own board.','curated','accepted');
INSERT INTO "summaries" VALUES(3,'R4_openai_client_partner_me','["media-ad-sales", "adtech-fluency", "new-business", "ai-in-workflow"]','Advertising and partnership seller who owns revenue end-to-end — prospect, qualify, build the business case, negotiate, close. Eight years across sports and entertainment media sales, enterprise revenue inside Disney/ESPN and Universal Parks, and consultative selling into ad-tech decision-makers on CDPs, clean rooms, identity graphs, and ad measurement. Sells with quantified, CPM- and ROI-modeled business cases rather than inventory sheets.','curated','accepted');
INSERT INTO "summaries" VALUES(4,'R5_luminance_commercial_director','["team-coaching", "hiring-onboarding", "proof-of-value", "ai-ml-solutions"]','Enterprise sales leader with eight years of full-cycle B2B revenue ownership and a track record of winning net-new Fortune 500 business from cold. Led a direct-report team of quota-carrying sellers through daily process coaching, 1:1 metric reviews, and forecast accountability — and spent four years as an enterprise recruiter before that, which makes hiring, ramping, and retaining sellers a core competency. Sells technology through diagnostic discovery and proof-of-value.','curated','accepted');
INSERT INTO "summaries" VALUES(5,'R6_admarketplace_director','["cpm-cpa-modeling", "adtech-fluency", "board-advisory", "unit-economics"]','Media and technology seller who sells intent and acquisition economics rather than impressions. Eight years of full-cycle, top-performing B2B and media revenue ownership — including net-new Fortune 500 wins from cold and a proof-of-concept that opened a multi-million-dollar expansion. Concurrently serves as strategy consultant to a healthcare AI startup, building board-level competitive analyses and unit-economics models, which keeps the commercial conversation fluent at the CFO and founder level.','curated','accepted');
INSERT INTO "summaries" VALUES(6,'R7_fox_weather_director','["sponsorship", "cross-platform", "cpm-cpa-modeling", "vertical-gtm"]','Media and sponsorship seller with eight years of revenue ownership, currently selling integrated print-and-digital partnerships across NFL and MLB team properties. Builds proposals the way a client''s finance team evaluates them — blended cross-platform CPM, reach and recall benchmarking, and cost-per-acquisition modeled against category benchmarks — so the investment is defensible at renewal, not just at signature.','curated','accepted');
INSERT INTO "summaries" VALUES(7,'R8_bairesdev_vp_sales','["managed-services-sales", "team-coaching", "buy-vs-build", "new-business"]','In technology services, the competitor is almost never the other vendor on the shortlist. It is the client''s own hiring plan. I spent five years inside an IT services and staffing firm learning that objection from the inside — opening net-new managed services logos, producing more than half the revenue on a major pharma account, and winning a proof-of-concept that converted into a multi-million-dollar expansion — and now sit on the buy side of that same conversation as strategy consultant to an early-stage AI company.','curated','accepted');
INSERT INTO "summaries" VALUES(8,'R9_knit_growth_marketing','["demand-generation", "qualification", "growth-efficiency", "marketing-sales-alignment"]','Most pipeline problems are definitional before they are volumetric. Marketing and sales rarely mean the same thing by ''qualified,'' and the gap between those definitions is where forecast accuracy quietly dies. I have spent eight years on the receiving end of it — sourcing 125 net-new qualified leads a week and qualifying on budget mechanics rather than expressed interest — and most recently built a GTM engine from nothing: segmentation, channel strategy, pricing, and the efficiency targets the business is managed against.','curated','accepted');
INSERT INTO "summaries" VALUES(9,'R10_mri_simmons_audience','["data-solutions", "multi-stakeholder-selling", "account-expansion", "primary-research"]','Selling into a holding company is rarely a selling problem. It is a routing problem. Eight years of enterprise selling has mostly been that routing work — finding the team whose problem the incumbent relationship did not touch. Translating what a dataset makes possible into something a buyer can commit budget to is the throughline.','curated','accepted');
INSERT INTO "summaries" VALUES(10,'R11_magellan_measurement','["audience-measurement", "account-expansion", "growth-efficiency", "media-ad-sales"]','Measurement rarely stalls on the technology. It stalls on accountability. I come at it from both sides of the ad transaction — selling advertising and working advertisers through their budget mechanics to understand who answers for how it performs — and most recently built the measurement framework an AI business is now run against. Setting the metric and telling the story from it are the same job.','curated','accepted');
INSERT INTO "summaries" VALUES(11,'R12_meridian_gtm','["gtm-strategy", "market-segmentation", "customer-discovery", "unit-economics"]','I think about go-to-market the way an economist thinks about a market: start at the macro level and work down until you find the specific thing creating the gap. Most of the time the ''no'' isn''t about the product — it''s a systemic issue in how a business is funded, structured, or governed that nobody has named yet. What I bring to a GTM team is the diagnostic front end — discovery that produces a real segmentation, competitive work that produces a defensible position, and unit economics that tell you early whether the motion can ever pay back.','curated','accepted');
INSERT INTO "summaries" VALUES(12,'R13_samba_platform_sales','["data-solutions", "partner-negotiation", "multi-stakeholder-selling", "market-sizing"]','Selling data into a platform is not a media sale. It is a roadmap decision, routed through people who carry no media number — product, engineering, legal, finance. I have spent most of my career selling into exactly that kind of room, and now translate data into the frameworks decisions actually get made on — a category sized, comparables benchmarked, a decision tree with base-rate odds attached to each path.','curated','accepted');
INSERT INTO "summaries" VALUES(13,'R14_smartly_agency_partnerships','["player-coach", "performance-management", "operating-cadence", "multi-stakeholder-selling"]','The failure mode of a player-coach seat is predictable: the quota you carry gets your Tuesday; the pod''s number becomes something you inspect on Friday. The leaders who beat that run their own deals on the same standard they hold the team to. That is the shape my last two roles have taken, and the other half of the job — building structure that does not exist yet — is what I have spent this year doing: RACI, escalation thresholds, weekly capacity forecast, one-page decision log.','curated','accepted');
INSERT INTO "summaries" VALUES(14,'R15_versant_transformation','["readiness-assessment", "stakeholder-alignment", "influence-without-authority", "operating-cadence"]','Adoption is not a communications problem, which is why communications plans so often fail to produce it. People adopt a change when the new way is easier than the workaround and when someone they report to is visibly accountable. Eight years of my career has been spent working through organizations I had no authority inside, and I do readiness work directly now — launch-readiness assessments, dated plans with named owners, and the operating cadence a company runs on.','curated','accepted');
INSERT INTO "summaries" VALUES(15,'R16_admarketplace_adv_success','["account-expansion", "team-coaching", "funding-source-diagnostics", "operating-cadence"]','The growth inside an advertiser book is almost never where the account plan says it is. It sits with a stakeholder nobody has met yet, behind a budget nobody has traced. Most of my career has been spent finding that — first for my own accounts, then teaching a team to find it without me in the room. I would rather set the standard once and let a team execute against it than inspect every deliverable that crosses my desk.','curated','accepted');
