BEGIN TRANSACTION;
CREATE TABLE achievement_evidence (
  achievement_id TEXT NOT NULL REFERENCES achievements(id),
  raw_bullet_id  INTEGER NOT NULL REFERENCES raw_bullets(id),
  PRIMARY KEY (achievement_id, raw_bullet_id)
);
CREATE TABLE achievement_tags (
  achievement_id TEXT NOT NULL REFERENCES achievements(id),
  tag_id         TEXT NOT NULL REFERENCES tags(id),
  weight         REAL NOT NULL DEFAULT 1.0,
  PRIMARY KEY (achievement_id, tag_id)
);
CREATE TABLE achievements (
  id         TEXT PRIMARY KEY,           -- psp-closed-deals …
  role_key   TEXT NOT NULL REFERENCES roles(key),
  confidence TEXT NOT NULL DEFAULT 'asserted',   -- verified | asserted | conflict
  notes      TEXT,
  metrics    TEXT                        -- JSON [{label,value,unit}]
);
CREATE TABLE bullets (
  id             INTEGER PRIMARY KEY,
  achievement_id TEXT NOT NULL REFERENCES achievements(id),
  kind           TEXT NOT NULL,          -- canonical | variant | learned
  angle          TEXT,                   -- fundraising, media, player-coach … (variants/learned)
  text           TEXT NOT NULL,
  chars          INTEGER,
  status         TEXT DEFAULT 'accepted',-- accepted | draft | rejected
  origin         TEXT DEFAULT 'curated', -- curated | artifact | gate1 | gate2
  score_adj      REAL DEFAULT 0,         -- learned preference (+keep / -reject)
  created_at     TEXT DEFAULT (datetime('now')),
  superseded_by  INTEGER REFERENCES bullets(id),
  supersede_why  TEXT
);
CREATE TABLE certifications (
  id INTEGER PRIMARY KEY, name TEXT NOT NULL, issuer TEXT, date TEXT, credential_id TEXT,
  status TEXT, source TEXT, tags TEXT
);
CREATE TABLE competencies (id INTEGER PRIMARY KEY, text TEXT NOT NULL UNIQUE, tags TEXT);
CREATE TABLE domain_fluency (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, tags TEXT);
CREATE TABLE education (
  id INTEGER PRIMARY KEY, school TEXT, degree TEXT, degree_variants TEXT, location TEXT, year TEXT,
  date_note TEXT, bullet_ids TEXT
);
CREATE TABLE enums (
  domain TEXT NOT NULL, code TEXT NOT NULL, label TEXT NOT NULL, sort INTEGER DEFAULT 0,
  PRIMARY KEY (domain, code)
);
CREATE TABLE expertise_areas (
  id INTEGER PRIMARY KEY, area TEXT NOT NULL, area_sort INTEGER, text TEXT NOT NULL, tags TEXT, sort INTEGER
);
CREATE TABLE feedback (
  id INTEGER PRIMARY KEY, jd_id TEXT REFERENCES job_descriptions(id),
  bullet_id INTEGER REFERENCES bullets(id), action TEXT NOT NULL,   -- keep | reject | edit
  edited_text TEXT, created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE followups (
  id INTEGER PRIMARY KEY, jd_id TEXT REFERENCES job_descriptions(id),
  gate INTEGER NOT NULL,                 -- 1 = baseline gate, 2 = per-JD gate
  question TEXT NOT NULL, answer TEXT, tag_id TEXT REFERENCES tags(id),
  resulting_bullet_id INTEGER REFERENCES bullets(id),
  asked_at TEXT DEFAULT (datetime('now')), answered_at TEXT
);
CREATE TABLE generated_resumes (
  id INTEGER PRIMARY KEY, jd_id TEXT REFERENCES job_descriptions(id), version TEXT,
  json TEXT NOT NULL, html_path TEXT, pdf_path TEXT, created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE jd_requirements (
  id INTEGER PRIMARY KEY, jd_id TEXT NOT NULL REFERENCES job_descriptions(id),
  tag_id TEXT REFERENCES tags(id), phrase TEXT, weight REAL DEFAULT 1.0, covered INTEGER
);
CREATE TABLE job_descriptions (
  id         TEXT PRIMARY KEY,           -- jd_<timestamp> or artifact doc id
  company    TEXT, title TEXT,
  text       TEXT NOT NULL,
  created_at TEXT DEFAULT (datetime('now')),
  origin     TEXT DEFAULT 'cli'          -- cli | artifact
);

Director, Go-To-Market — Advertiser Partnerships
New York, NY (Hybrid)

About the role
We are an AI-native ad-tech company helping brands reach high-intent audiences across conversational surfaces. We''re hiring a Director of Go-To-Market to own our advertiser partnerships motion from first conversation to signed contract, and to build the playbook the next five sellers will run.

What you''ll do
- Own full-cycle new business with brands and agencies: prospecting, discovery, business case, negotiation, and close.
- Build ROI and cost-per-acquisition business cases that a CMO and CFO can both defend; fluency in CPM, CPA, ROAS, and measurement is essential.
- Define segmentation, positioning, and pricing for new verticals; partner with product on packaging.
- Stand up channel and agency partnerships that scale beyond direct sales.
- Build forecasting and pipeline discipline in Salesforce; report weekly to the executive team.
- Hire, coach, and develop a small team of account executives as a player-coach.

What you''ll bring
- 7+ years in advertising sales, media sales, or ad tech with a track record of exceeding quota.
- Experience selling into complex, multi-stakeholder buying committees at enterprise brands.
- Working knowledge of clean rooms, CDPs, identity resolution, and first-party data.
- Comfort presenting to C-suite and board-level stakeholders.
- Hands-on use of generative AI tools (ChatGPT, Claude) in your daily workflow.
- Bonus: experience at an early-stage startup or building a GTM function from zero.
